namespace sv_e9befe0bb2074cb89627e112629e3c0c.Services;

public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            NotifyStateChanged();
        }
    }

    public string CurrentWarehouseName =>
        Warehouses.TryGetValue(_currentWarehouseId, out var name) ? name : _currentWarehouseId;

    public static IReadOnlyDictionary<string, string> Warehouses { get; } =
        new Dictionary<string, string>
        {
            ["WH-001"] = "Warehouse A — Main Distribution",
            ["WH-002"] = "Warehouse B — East Region",
            ["WH-003"] = "Warehouse C — West Region",
            ["WH-004"] = "Warehouse D — Cold Storage",
        };

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

namespace sv_e9befe0bb2074cb89627e112629e3c0c.Services;

public class InventoryAlertService
{
    private static readonly Random _random = new();

    private int _lastLowStockCount;

    public int LastLowStockCount => _lastLowStockCount;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches new data and broadcasts to all subscribers.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        _lastLowStockCount = await GetLowStockCountAsync(warehouseId);
        NotifyAlertDataChanged();
    }

    /// <summary>
    /// Fired whenever new alert data is available. All subscribed components should re-render.
    /// </summary>
    public event Action? OnAlertDataChanged;

    private void NotifyAlertDataChanged() => OnAlertDataChanged?.Invoke();
}

