@using sv_e9befe0bb2074cb89627e112629e3c0c.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">
    Viewing: <strong>@WarehouseState.CurrentWarehouseName</strong>
    <span class="text-secondary">(@WarehouseState.CurrentWarehouseId)</span>
</p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(AlertService.LastLowStockCount > 5 ? "text-danger" : "text-warning")">
                    @AlertService.LastLowStockCount
                </p>
                <p class="text-muted">items below minimum level</p>
                <small class="text-secondary">Polling every 10 seconds</small>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _pollingCts;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertDataChanged += OnAlertDataChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Initial fetch + start polling when page becomes visible
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _pollingCts?.Cancel();
        _pollingCts = new CancellationTokenSource();
        var token = _pollingCts.Token;

        _ = Task.Run(async () =>
        {
            using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            while (await timer.WaitForNextTickAsync(token))
            {
                await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            }
        }, token);
    }

    private void OnWarehouseChanged()
    {
        // Restart polling for the new warehouse and fetch immediately
        StartPolling();
        InvokeAsync(async () =>
        {
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            StateHasChanged();
        });
    }

    private void OnAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _pollingCts?.Cancel();
        _pollingCts?.Dispose();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertDataChanged -= OnAlertDataChanged;
    }
}

